1	#!/usr/bin/env node
2	// Write Form Builder XML (the format of SMARTFORMS > Utilities > Upload) from a
3	// form spec — the last step of the SmartForm-from-PDF skill. The XML goes to SAP
4	// with the MCP tool CreateSmartForm.
5	//
6	//   node write-form.mjs <spec.json> [--out FORM.xml]
7	//
8	// Spec (lengths in mm, line widths in points):
9	// { form, caption?, language?: "EN", pageFormat?: "DINA4", orientation?: "P",
10	//   style: "ZSTYLE",                       // form style (STDSTYLE); must exist
11	//   interface?: [{ name, typing?: "TYPE", type, optional? }],   // importing parameters
12	//   tables?: [{ name, typing?: "LIKE", type }],                  // TABLES parameters
13	//   globals?: [{ name, typing?: "TYPE", type }],
14	//   windows: [{ name, caption?, type?: "T" (secondary) | "M" (main), x, y, w, h,
15	//               border?: { th, sides?: "LTRB" },  style?,
16	//               nodes: [ Text | Template ] }] }
17	// Text:     { kind: "text", name?, lines: [{ f: "L1", t: "Label &GS_X-Y&" }], style? }
18	// Template: { kind: "template", name?, left?, top?, rows: [{ h, cols: [w...] }],
19	//             cells?: [{ row, col, borders?: { l, t, r, b } (pt), shade? (0..100),
20	//                        nodes: [Text] }] }   row / col from 1
21	import { readFileSync, writeFileSync } from 'node:fs';
22	import { pathToFileURL } from 'node:url';
23	
24	const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
25	// el('A', 'text') → <A>text</A>; el('A', [children]) → nested; null / undefined children dropped
26	function el(tag, body, attrs = '') {
27	  if (body === undefined || body === null) return '';
28	  if (Array.isArray(body)) {
29	    const inner = body.filter((b) => b !== undefined && b !== null && b !== '').join('');
30	    return inner ? `<${tag}${attrs}>${inner}</${tag}>` : `<${tag}${attrs}/>`;
31	  }
32	  return `<${tag}${attrs}>${esc(body)}</${tag}>`;
33	}
34	const num = (v, d = 2) => Number(v).toFixed(d);
35	const n3 = (v) => String(Math.round(v)).padStart(3, '0');
36	
37	// SAP language key (1 char) for the XML's T_CAPTION rows
38	const LANG1 = { EN: 'E', DE: 'D', KO: '3', JA: 'J', ZH: '1', FR: 'F', ES: 'S', IT: 'I', PT: 'P', RU: 'R', TR: 'T', HU: 'H', PL: 'L', CS: 'C', NL: 'N' };
39	
40	const STD_INTERFACE = [
41	  ['E', 'DOCUMENT_OUTPUT_INFO', 'SSFCRESPD', false], ['E', 'JOB_OUTPUT_INFO', 'SSFCRESCL', false], ['E', 'JOB_OUTPUT_OPTIONS', 'SSFCRESOP', false],
42	  ['I', 'ARCHIVE_INDEX', 'TOA_DARA', true], ['I', 'ARCHIVE_INDEX_TAB', 'TSFDARA', true], ['I', 'ARCHIVE_PARAMETERS', 'ARC_PARAMS', true],
43	  ['I', 'CONTROL_PARAMETERS', 'SSFCTRLOP', true], ['I', 'MAIL_APPL_OBJ', 'SWOTOBJID', true], ['I', 'MAIL_RECIPIENT', 'SWOTOBJID', true],
44	  ['I', 'MAIL_SENDER', 'SWOTOBJID', true], ['I', 'OUTPUT_OPTIONS', 'SSFCOMPOP', true], ['I', 'USER_SETTINGS', 'TDBOOL', true, "'X'"],
45	];
46	const STD_EXCEPTIONS = ['FORMATTING_ERROR', 'INTERNAL_ERROR', 'SEND_ERROR', 'USER_CANCELED'];
47	
48	// a text line holds 132 characters (TDLINE): a longer one goes on in '=' lines;
49	// it is cut only outside <format> and &field& tags
50	export function tdlines(text, max = 132) {
51	  const out = [];
52	  let rest = String(text);
53	  while (rest.length > max) {
54	    let cut = max;
55	    const inside = (k) => { const lt = rest.lastIndexOf('<', k - 1), gt = rest.lastIndexOf('>', k - 1); const amp = (rest.slice(0, k).match(/&/g) || []).length; return lt > gt || amp % 2 === 1; };
56	    while (cut > 1 && inside(cut)) cut--;
57	    out.push(rest.slice(0, cut));
58	    rest = rest.slice(cut);
59	  }
60	  out.push(rest);
61	  return out;
62	}
63	
64	export function writeForm(spec) {
65	  const form = String(spec.form).toUpperCase();
66	  const lang1 = LANG1[(spec.language || 'EN').toUpperCase()] || 'E';
67	  const counters = {};
68	  const auto = (prefix) => `%${prefix}${(counters[prefix] = (counters[prefix] || 0) + 1)}`;
69	  const tcap = (objtype, iname, caption) => el('T_CAPTION', [el('item', [el('LANGU', lang1), el('FORMNAME', form), el('OBJTYPE', objtype), el('INAME', iname), caption ? el('CAPTION', caption) : null])]);
70	
71	  const sideAttr = (tag, th) => el(tag, [el('THICKNESS', num((th || 0) * 20)), el('THICKNESSU', 'TW'), el('DISTANCE', '0.00'), el('DISTANCEU', 'CM'), el('COLOR', [el('RED', '000'), el('GREEN', '000'), el('BLUE', '000'), el('TRANS', '000')])]);
72	  // output attributes of a node: position (windows), cell (template texts), border, style
73	  const outattr = (o = {}) => {
74	    const iname = auto('OUTATTRIB');
75	    const b = o.border || {};
76	    const sides = b.sides || 'LTRB';
77	    const th = (s) => (b.th && sides.includes(s) ? b.th : 0);
78	    return el('sf:OUTATTR', [el('sf:OUTATTR', [
79	      el('NAME', [el('INAME', iname)]),
80	      // the style a text prints in is the one of its output options (or its parents')
81	      o.style ? el('STDSTYLE', o.style) : null,
82	      o.lineType ? el('T_LINETYPE', o.lineType) : null,
83	      o.line ? el('T_LINENR', n3(o.line)) : null,
84	      o.cell ? el('T_CELLNR', n3(o.cell)) : null,
85	      el('U_WFRAME', 'PT'), el('U_WBOXV', 'CM'), el('U_WBOXH', 'CM'),
86	      o.x !== undefined ? el('WLEFT', num(o.x)) : null, el('U_WLEFT', 'MM'),
87	      o.w !== undefined ? el('WWIDTH', num(o.w)) : null, el('U_WWIDTH', 'MM'),
88	      o.y !== undefined ? el('WTOP', num(o.y)) : null, el('U_WTOP', 'MM'),
89	      o.h !== undefined ? el('WHEIGHT', num(o.h)) : null, el('U_WHEIGHT', 'MM'),
90	      el('BORDER', [th('L') ? el('LEFTLINE', 'X') : null, sideAttr('LEFTATTR', th('L')), th('T') ? el('TOPLINE', 'X') : null, sideAttr('TOPATTR', th('T')), th('R') ? el('RIGHTLINE', 'X') : null, sideAttr('RIGHTATTR', th('R')), th('B') ? el('BOTTOMLINE', 'X') : null, sideAttr('BOTTOMATTR', th('B'))]),
91	      tcap('OA', iname),
92	    ])]);
93	  };
94	  const node = (type, obj, out, succ = []) => el('sf:NODE', [el('NODETYPE', type), el('sf:OBJ', [obj]), out || null, el('sf:SUCC', succ.map((s) => el('sf:item', [s])))]);
95	
96	  const textNode = (t, cellPos) => {
97	    const iname = t.name || auto('TEXT');
98	    const obj = el('sf:TEXT', [
99	      el('NAME', [el('INAME', iname)]),
100	      el('CAPTION', t.caption || iname),
101	      el('NOLANGUAGE', 'X'),
102	      el('APPMODE', 'P'),
103	      el('TEXT', t.lines.flatMap((l) => tdlines(l.t ?? '').map((piece, i) => el('item', [el('TDFORMAT', i ? '=' : l.f || '*'), el('TDLINE', piece)])))),
104	      t.style ? el('STYLE_NAME', t.style) : null,
105	      el('TEXT_AREA', [el('ENABLED', 'F'), el('NCOLS', '0'), el('NROWS', '0')]),
106	      tcap('TI', iname, t.caption || iname),
107	    ]);
108	    return node('TI', obj, outattr({ ...(cellPos || {}), style: t.style }));
109	  };
110	
111	  // CELLS items of a template line (name LINEn) or a table line type: widths and borders
112	  const cellItems = (lineName, cols, cellOf) => cols.map((w, j) => {
113	    const q = cellOf(j + 1) || {};
114	    const b = q.borders || {};
115	    const tw = (pt) => num((pt || 0) * 20); // border widths in twips
116	    const color = (tag, used) => el(tag, [el('RED', '000'), el('GREEN', '000'), el('BLUE', '000'), used ? el('USED', 'X') : null]);
117	    return el('item', [
118	      el('NAME', lineName), el('COLUMNNR', n3(j + 1)), el('CWIDTH', num(w)), el('U_CWIDTH', 'MM'), el('SHADING', n3(q.shade || 0)),
119	      el('BORDERS', [el('item', [
120	        el('IDX', '001'), el('INTENSITY', n3(q.shade || 0)),
121	        el('LLEFT', tw(b.l)), el('LLEFT_U', 'TW'), el('LTOP', tw(b.t)), el('LTOP_U', 'TW'),
122	        el('LRIGHT', tw(b.r)), el('LRIGHT_U', 'TW'), el('LBOTTOM', tw(b.b)), el('LBOTTOM_U', 'TW'),
123	        color('FILLCOLOR', !!q.shade), color('CLEFT', !!b.l), color('CTOP', !!b.t), color('CRIGHT', !!b.r), color('CBOTTOM', !!b.b),
124	      ])]),
125	    ]);
126	  });
127	  const pattern = el('PATTERN', [el('PATTNUM', '0000'), el('FRAME', '0.00'), el('U_FRAME', 'TW')]);
128	
129	  const templateNode = (tp) => {
130	    const iname = tp.name || auto('TEMPLATE');
131	    const lines = tp.rows.map((r, i) => el('item', [el('NAME', `LINE${i + 1}`), el('LINEFROM', n3(i + 1)), el('LINETO', n3(i + 1)), el('LHEIGHT', num(r.h)), el('U_LHEIGHT', 'MM'), el('SHADING', '000')]));
132	    const cells = tp.rows.flatMap((r, i) => cellItems(`LINE${i + 1}`, r.cols, (c) => (tp.cells || []).find((q) => q.row === i + 1 && q.col === c)));
133	    const width = Math.max(...tp.rows.map((r) => r.cols.reduce((s, w) => s + w, 0)));
134	    const obj = el('sf:SECTION', [
135	      el('NAME', [el('INAME', iname)]),
136	      el('CAPTION', tp.caption || iname),
137	      el('SECTTYPE', 'S'), el('OTABTYPE', 'S'), el('U_FHEIGHT', 'CM'),
138	      pattern,
139	      el('USEBORDER', 'X'),
140	      el('WIDTH', num(width)), el('U_WIDTH', 'MM'),
141	      el('APPMODE', 'L'), // C would centre the template in its window
142	      tp.left ? el('LEFT', num(tp.left)) : null, el('U_LEFT', 'MM'),
143	      tp.top ? el('TOP', num(tp.top)) : null, el('U_TOP', 'MM'),
144	      el('U_SB', 'CM'), el('U_SA', 'CM'),
145	      el('STATLINES', lines),
146	      el('CELLS', cells),
147	      tcap('SE', iname, tp.caption || iname),
148	    ]);
149	    const kids = [];
150	    for (const q of tp.cells || []) for (const t of q.nodes || []) kids.push(textNode(t, { line: q.row, cell: q.col }));
151	    return node('SE', obj, outattr({}), kids);
152	  };
153	
154	  // a section node without layout of its own (loop, table row, table cell)
155	  const section = (type, name, caption, extra, out, kids) => node('SE', el('sf:SECTION', [
156	    el('NAME', [el('INAME', name)]), el('CAPTION', caption || name), el('SECTTYPE', type), ...extra,
157	    el('U_FHEIGHT', 'CM'), pattern, el('U_WIDTH', 'CM'), el('U_LEFT', 'CM'), el('U_TOP', 'CM'), el('U_SB', 'CM'), el('U_SA', 'CM'),
158	    tcap('SE', name, caption || name),
159	  ]), out, kids);
160	  const loopData = (tb) => [el('DATATYPE', 'L'), el('TABNAME', tb.data), el('TABHTYPE', 'I'), el('TABHEADER', tb.into)];
161	
162	  // Table: { kind: "table", name?, data: "IT_ITEMS", into: "GS_ITEM", width?, style?,
163	  //   lineTypes: [{ name: "%LTYPE1", cols: [w...], cells?: [{ col, borders?, shade? }] }],
164	  //   header?: [Row], body: [Row], footer?: [Row] }   Row: { type: "%LTYPE1", cells: [[Text...] per column] }
165	  // the body rows print once per line of `data`, read into `into`
166	  const tableNode = (tb) => {
167	    const iname = tb.name || auto('TABLE');
168	    const lt = tb.lineTypes;
169	    const width = tb.width || Math.max(...lt.map((l) => l.cols.reduce((s, w) => s + w, 0)));
170	    const obj = el('sf:SECTION', [
171	      el('NAME', [el('INAME', iname)]), el('CAPTION', tb.caption || iname),
172	      el('SECTTYPE', 'C'), ...loopData(tb),
173	      el('OTABTYPE', 'D'), el('OTABHEADER', 'A'), el('OTABFOOTER', 'A'),
174	      // the space kept free for the footer at a page break (SAP requires it)
175	      el('FHEIGHT', num(tb.footerHeight ?? Math.max(5, 5 * (tb.footer || []).length))), el('U_FHEIGHT', 'MM'), pattern, el('USEBORDER', 'X'),
176	      el('WIDTH', num(width)), el('U_WIDTH', 'MM'), el('APPMODE', 'L'),
177	      el('U_LEFT', 'MM'), el('U_TOP', 'MM'), el('U_SB', 'CM'), el('U_SA', 'CM'),
178	      el('DYNLINES', lt.map((l, i) => el('item', [el('NAME', l.name), i === 0 ? el('DEFAULTVAL', 'X') : null, el('SHADING', '000')]))),
179	      el('CELLS', lt.flatMap((l) => cellItems(l.name, l.cols, (c) => (l.cells || []).find((q) => q.col === c)))),
180	      tcap('SE', iname, tb.caption || iname),
181	    ]);
182	    const row = (r) => {
183	      const rname = auto('ROW');
184	      const cells = (r.cells || []).map((texts, j) => section('E', auto('CELL'), `Cell ${j + 1}`, [], outattr({}), (texts || []).map((t) => textNode(t))));
185	      return section('R', rname, r.caption || rname, [], outattr({ lineType: r.type }), cells);
186	    };
187	    const event = (type, caption, rows) => node('EV', el('sf:EVENT', [el('NAME', [el('INAME', auto('EVENT'))]), el('CAPTION', caption), el('EVTYPE', type)]), null, (rows || []).map(row));
188	    return node('SE', obj, outattr({ style: tb.style }), [event('H', 'Header', tb.header), event('B', 'Main Area', tb.body), event('F', 'Footer', tb.footer)]);
189	  };
190	
191	  // Loop: { kind: "loop", name?, data: "IT_ITEMS", into: "GS_ITEM", nodes: [...] } — its nodes print once per line
192	  const loopNode = (lp) => {
193	    const iname = lp.name || auto('LOOP');
194	    return section('L', iname, lp.caption || iname, loopData(lp), outattr({}), (lp.nodes || []).map(anyNode));
195	  };
196	
197	  const anyNode = (n) => (n.kind === 'template' ? templateNode(n) : n.kind === 'table' ? tableNode(n) : n.kind === 'loop' ? loopNode(n) : textNode(n));
198	
199	  const windowNode = (w) => {
200	    const iname = w.name || auto('WINDOW');
201	    const kids = (w.nodes || []).map(anyNode);
202	    const proc = el('sf:PROC_CTRL', [el('sf:NODE', [el('NODETYPE', 'RC'), el('sf:SUCC', kids.map((k) => el('sf:item', [k])))])]);
203	    const obj = el('sf:WINDOW', [el('NAME', [el('INAME', iname)]), el('CAPTION', w.caption || iname), el('WTYPE', w.type || 'T'), tcap('WI', iname, w.caption || iname), proc]);
204	    return node('WI', obj, outattr({ x: w.x, y: w.y, w: w.w, h: w.h, border: w.border }));
205	  };
206	
207	  const page = el('sf:PAGE', [
208	    el('NAME', [el('INAME', 'FIRST')]), el('CAPTION', 'Page 1'),
209	    el('NUMB_MODE', 'I'), el('NUMB_TYPE', 'A'), el('PAGEORTN', spec.orientation || 'P'),
210	    tcap('PA', 'FIRST', 'Page 1'),
211	  ]);
212	  const pageNode = node('PA', page, null, spec.windows.map(windowNode));
213	  const pagetree = el('sf:PAGETREE', [el('sf:NODE', [el('NODETYPE', 'RP'), el('sf:SUCC', [el('sf:item', [pageNode])])])]);
214	
215	  const iface = [
216	    ...STD_INTERFACE.map(([io, name, type, opt, def]) => el('item', [el('IOTYPE', io), el('NAME', name), el('TYPING', 'TYPE'), el('TYPENAME', type), opt ? el('OPTIONAL', 'X') : null, el('BYVALUE', 'X'), def ? el('DEFAULTVAL', def) : null, el('STANDARD', 'X')])),
217	    ...(spec.interface || []).map((p) => el('item', [el('IOTYPE', 'I'), el('NAME', p.name), el('TYPING', p.typing || 'TYPE'), el('TYPENAME', p.type), p.optional ? el('OPTIONAL', 'X') : null])),
218	    ...(spec.tables || []).map((p) => el('item', [el('IOTYPE', 'T'), el('NAME', p.name), el('TYPING', p.typing || 'LIKE'), el('TYPENAME', p.type)])),
219	    ...STD_EXCEPTIONS.map((x) => el('item', [el('IOTYPE', 'X'), el('NAME', x), el('STANDARD', 'X')])),
220	  ];
221	  const gdata = (spec.globals || []).map((g) => el('item', [el('NAME', g.name), el('TYPING', g.typing || 'TYPE'), el('TYPENAME', g.type)]));
222	
223	  const body = [
