168	function gridOf(rules, texts) {
169	  const H = rules.filter((s) => s.dir === 'H'), V = rules.filter((s) => s.dir === 'V');
170	  const xs = uniq([...V.map((s) => s.pos), ...H.flatMap((s) => [s.a, s.b])]);
171	  const ys0 = uniq([...H.map((s) => s.pos), ...V.flatMap((s) => [s.a, s.b])]);
172	  if (xs.length < 2 || ys0.length < 2) return null;
173	  const x0 = xs[0], x1 = xs[xs.length - 1], y0 = ys0[0], y1 = ys0[ys0.length - 1];
174	  // a cell prints a line only when the whole line height fits in it: a text goes into
175	  // the grid when [top, top + line] crosses no rule and no other text's start —
176	  // the others are left for windows over the grid
177	  const cand = texts.filter((t) => t.x >= x0 - 0.3 && t.x < x1 - 0.3 && t.y > y0 + 0.3 && t.y <= y1 + 0.3).sort((a, b) => a.top - b.top);
178	  const mine = [];
179	  const hr = (t) => H.filter((s) => s.a <= t.x + 0.3 && s.b >= t.x + 0.3);
180	  for (const t of cand) {
181	    const ls = t.fmt.ls ?? LN_MM;
182	    const ruleAbove = Math.max(-1e9, ...hr(t).filter((s) => s.pos <= t.y).map((s) => s.pos));
183	    if (t.top < ruleAbove - 0.05) continue; // the line would start above the cell
184	    // any y of the grid (also where a vertical rule starts or ends elsewhere) cuts the whole template row
185	    if (ys0.some((y) => y > t.top + 0.05 && y < t.top + ls - 0.05)) continue;
186	    const clash = mine.some((o) => Math.abs(o.top - t.top) > 0.2 && ((o.top > t.top && o.top < t.top + ls - 0.05) || (t.top > o.top && t.top < o.top + (o.fmt.ls ?? LN_MM) - 0.05)));
187	    if (clash) continue;
188	    mine.push(t);
189	  }
190	  const ys = uniq([...ys0, ...mine.map((t) => Math.max(y0, t.top))], 0.2);
191	  const covers = (list, pos, a, b) => list.find((s) => Math.abs(s.pos - pos) < 0.3 && s.a <= a + 0.4 && s.b >= b - 0.4);
192	  const th = (r) => (r ? Math.max(0.1, (r.th * 72) / 25.4) : 0); // mm → pt
193	  const rows = [];
194	  const placed = [];
195	  for (let i = 0; i + 1 < ys.length; i++) {
196	    const top = ys[i], bot = ys[i + 1];
197	    if (bot - top < 0.2) continue;
198	    const mid = (top + bot) / 2;
199	    // the texts that start in this row
200	    const here = mine.filter((t) => Math.abs(Math.max(y0, t.top) - top) < 0.25);
201	    // columns end at the vertical rules crossing the row and where a rule along its top or
202	    // bottom edge starts or ends (a cell border is all or nothing)
203	    const edgeEnds = H.filter((s) => Math.abs(s.pos - top) < 0.3 || Math.abs(s.pos - bot) < 0.3).flatMap((s) => [s.a, s.b]);
204	    const ruleCuts = uniq([x0, x1, ...V.filter((s) => s.a <= mid && s.b >= mid).map((s) => s.pos), ...edgeEnds]);
205	    // the outer edges stay where they are (every row has the grid's width)
206	    const cuts = [x0, ...uniq([...ruleCuts, ...here.map((t) => t.left)], 0.3).filter((x) => x > x0 + 0.2 && x < x1 - 0.2), x1];
207	    const cells = [];
208	    for (let j = 0; j + 1 < cuts.length; j++) {
209	      const a = cuts[j], b = cuts[j + 1];
