239	export function planForm(layout, catalog, opts = {}) {
240	  const page = layout.page;
241	  const choices = styleChoices(catalog);
242	  if (!choices.length) throw new Error('no usable paragraph in the style catalog');
243	  // pieces joined only across a single blank: a wider gap is a column gap (in a
244	  // template the second part would wrap in the first part's cell)
245	  const runs = (page.texts ? mergeRuns(page.texts, 1.1) : page.runs).map((t, i) => ({ ...t, i }));
246	  const report = { templates: 0, windows: 0, rules: 0, texts: runs.length, inCells: 0, fonts: {} };
247	  // the form style: the one that serves most texts best
248	  const votes = {};
249	  for (const t of runs) { const c = pickFormat(choices, t); votes[c.style] = (votes[c.style] || 0) + 1; }
250	  const formStyle = opts.style || Object.entries(votes).sort((a, b) => b[1] - a[1])[0][0];
251	  // every text's format, and from it where its cell / window must start
252	  for (const t of runs) {
253	    t.fmt = pickFormat(choices, t, 'LEFT', formStyle);
254	    const ls = t.fmt.ls ?? LN_MM;
255	    t.top = +(t.y - ls).toFixed(2);
256	    t.left = +(t.x - (t.fmt.left || 0)).toFixed(2);
257	    const key = `${sapFamily(t)} ${t.pt}${t.bold ? 'B' : ''} → ${t.fmt.style}/${t.fmt.para}${t.fmt.char ? '+' + t.fmt.char : ''} (${t.fmt.fam} ${t.fmt.pt}${t.fmt.bold ? 'B' : ''})`;
258	    report.fonts[key] = (report.fonts[key] || 0) + 1;
259	  }
260	  const textNode = (t) => ({ kind: 'text', lines: [{ f: t.fmt.para, t: t.fmt.char ? `<${t.fmt.char}>${literal(t.text)}</>` : literal(t.text) }], style: t.fmt.style !== formStyle ? t.fmt.style : undefined });
261	
262	  const windows = [];
263	  const pageW = page.widthMm, pageH = page.heightMm;
264	  // a form needs a main window: an empty one at the bottom margin
265	  windows.push({ name: 'MAIN', type: 'M', x: 10, y: +(pageH - 8).toFixed(2), w: 20, h: 4, nodes: [] });
266	
267	  const used = new Set();
268	  const { H, V } = rulesOf(page);
269	  let gi = 0, ri = 0;
270	  for (const g of groups({ H, V })) {
271	    const grid = gridOf(g, runs.filter((t) => !used.has(t.i)));
272	    if (!grid) {
273	      // a lone rule: a one-cell template whose cell border is the rule (a window frame
274	      // prints only when the window prints something, a template border always)
275	      for (const s of g) {
276	        ri++;
277	        const pt = Math.max(0.1, (s.th * 72) / 25.4);
278	        const len = +(s.b - s.a).toFixed(2);
279	        windows.push(s.dir === 'H'
280	          ? { name: `%RULE${ri}`, caption: 'Rule', x: +s.a.toFixed(2), y: +s.pos.toFixed(2), w: +Math.min(len + 0.5, pageW - s.a).toFixed(2), h: 1, nodes: [{ kind: 'template', rows: [{ h: 0.3, cols: [len] }], cells: [{ row: 1, col: 1, borders: { t: pt }, nodes: [] }] }] }
281	          : { name: `%RULE${ri}`, caption: 'Rule', x: +s.pos.toFixed(2), y: +s.a.toFixed(2), w: 1, h: +Math.min(len + 0.5, pageH - s.a).toFixed(2), nodes: [{ kind: 'template', rows: [{ h: len, cols: [0.3] }], cells: [{ row: 1, col: 1, borders: { l: pt }, nodes: [] }] }] });
282	      }
283	      continue;
284	    }
285	    gi++;
286	    for (const t of grid.placed) used.add(t.i);
287	    report.inCells += grid.placed.length;
288	    // columns from the rounded cut positions: every row adds up to the same width
289	    const rd = (v) => Math.round(v * 100) / 100;
290	    const rows = grid.rows.map((r) => ({ h: rd(r.h), cols: r.cells.map((c) => +(rd(c.x + c.w) - rd(c.x)).toFixed(2)) }));
291	    // a grid running into the page edge: its window ends there, the last columns give way
292	    const maxW = rd(Math.min(grid.w, pageW - grid.x - 0.5));
293	    for (const r of rows) { let over = +(r.cols.reduce((s, w) => s + w, 0) - maxW).toFixed(2); for (let k = r.cols.length - 1; k >= 0 && over > 0; k--) { const cut = Math.min(over, r.cols[k] - 0.1); r.cols[k] = +(r.cols[k] - cut).toFixed(2); over = +(over - cut).toFixed(2); } }
294	    const cells = [];
295	    grid.rows.forEach((r, i) => r.cells.forEach((c, j) => {
296	      const b = c.borders;
297	      if (!c.texts.length && !b.l && !b.r && !b.t && !b.b) return;
298	      cells.push({ row: i + 1, col: j + 1, borders: b, nodes: c.texts.map(textNode) });
299	    }));
300	    windows.push({ name: `%WINDOW${gi}`, caption: `Grid ${gi}`, x: +grid.x.toFixed(2), y: +grid.y.toFixed(2), w: +Math.min(grid.w + 0.5, pageW - grid.x).toFixed(2), h: +Math.min(grid.h + 0.5, pageH - grid.y).toFixed(2), nodes: [{ kind: 'template', rows, cells }] });
301	  }
302	
303	  // free texts: one window each
304	  let wi = 0;
305	  for (const t of runs) {
306	    if (used.has(t.i)) continue;
307	    wi++;
308	    const ls = t.fmt.ls ?? LN_MM;
309	    // as wide as the line allows: SAP's font may run wider than the PDF's, and a
310	    // window too narrow wraps the text onto a line that is cut off
311	    let right = pageW - 1;
312	    for (const o of runs) if (o !== t && o.x > t.x + 0.5 && o.y > t.top && o.top < t.y) right = Math.min(right, o.left - 0.3);
313	    for (const v of V) if (v.pos > t.x + 0.5 && v.a < t.y && v.b > t.top) right = Math.min(right, v.pos - 0.2);
314	    // (it may overlap a neighbour rather than wrap: SAP's font can run wider)
315	    let x = t.left;
316	    let w = Math.max(t.w * 1.3 + 2, right - t.left);
317	    // a centred / right-aligned paragraph (the only one with the font): the window is
318	    // placed so that the alignment puts the text where the PDF has it
319	    const pw = printedWidth(t);
320	    if (t.fmt.align === 'CENTER') { const c = t.x + t.w / 2; w = Math.min(pw * 1.3 + 4, 2 * c, 2 * (pageW - c) - 0.4); x = c - w / 2; }
321	    else if (t.fmt.align === 'RIGHT') { const r = t.x + t.w + (t.fmt.right || 0); w = Math.min(pw * 1.3 + 4, r); x = r - w; }
322	    windows.push({ name: `%TEXTWIN${wi}`, caption: String(t.text).slice(0, 30), x: +Math.max(0, x).toFixed(2), y: t.top, w: +Math.min(w, pageW - Math.max(0, x) - 0.2).toFixed(2), h: +Math.min(ls + 0.6, pageH - t.top - 0.2).toFixed(2), nodes: [textNode(t)] });
323	  }
324	  report.templates = gi;
325	  report.rules = ri;
326	  report.windows = windows.length;
327	  const pf = pageFormatOf(pageW, pageH, opts.pageFormats);
328	  if (!pf.exact) report.pageFormat = `no page format of ${pageW} x ${pageH} mm — ${pf.name} used`;
329	  return {
330	    spec: { form: opts.form || 'ZSC4SAP_DRAFT', caption: opts.caption || 'Form from PDF', language: opts.language || 'EN', pageFormat: pf.name, orientation: pf.orientation, style: formStyle, windows },
331	    report,
332	  };
333	}
