336	  const opt = (k) => { const i = argv.indexOf(k); return i >= 0 ? argv[i + 1] : undefined; };
337	  if (!argv[0] || !opt('--styles')) { console.error('usage: node plan-form.mjs <layout.json> --styles <catalog.json> --form ZNAME [--out spec.json]'); process.exit(2); }
