1	#!/usr/bin/env node
2	// Compare two page layouts (read-pdf.mjs output): the source the form was made
3	// from and what SAP printed from the generated form. Every source text run is
4	// looked up in the print by its text, position (mm), size and weight; every
5	// source rule by its direction, position and extent.
6	//
7	//   node compare-layout.mjs <source.json|.pdf> <printed.json|.pdf> [--out report.json]
8	//
9	// Report: { score, texts: { source, matched, moved[], font[], missing[], extra[] },
10	//           rules: { source, matched, missing[], extra[] } }
11	// score = 0.75 × text score + 0.25 × rule score (0..100); a text found at the
12	// wrong place / in the wrong size counts half.
13	import { readFileSync, writeFileSync } from 'node:fs';
14	import { pathToFileURL } from 'node:url';
15	import { mergeRules, readPdf } from './read-pdf.mjs';
16	
17	const POS = 0.6;  // mm
18	const RULE = 0.4; // mm
19	
20	const load = (f) => (/\.pdf$/i.test(f) ? readPdf(readFileSync(f)).page : JSON.parse(readFileSync(f, 'utf8')).page);
21	const norm = (s) => String(s).replace(/\s+/g, ' ').trim();
22	
23	function rules(page) {
24	  const out = [];
25	  const add = (dir, pos, a, b) => { if (b - a > 0.3) out.push({ dir, pos, a, b }); };
26	  for (const l of page.lines || []) {
27	    if (Math.abs(l.y1 - l.y2) < 0.05) add('H', l.y1, Math.min(l.x1, l.x2), Math.max(l.x1, l.x2));
28	    else if (Math.abs(l.x1 - l.x2) < 0.05) add('V', l.x1, Math.min(l.y1, l.y2), Math.max(l.y1, l.y2));
29	  }
30	  for (const r of page.rects || []) {
31	    if (r.fill !== undefined && r.h < 0.8 && r.w > r.h) add('H', r.y + r.h / 2, r.x, r.x + r.w);
32	    else if (r.fill !== undefined && r.w < 0.8) add('V', r.x + r.w / 2, r.y, r.y + r.h);
33	    else if (r.stroke !== undefined) { add('H', r.y, r.x, r.x + r.w); add('H', r.y + r.h, r.x, r.x + r.w); add('V', r.x, r.y, r.y + r.h); add('V', r.x + r.w, r.y, r.y + r.h); }
34	  }
35	  return mergeRules(out);
36	}
37	
38	export function compareLayouts(src, out) {
39	  const S = src.runs || src.texts, O = (out.runs || out.texts).map((t) => ({ ...t, used: false }));
40	  const tx = { source: S.length, matched: 0, moved: [], font: [], missing: [], extra: [] };
41	  let pts = 0;
42	  for (const t of S) {
43	    const want = norm(t.text);
44	    const same = O.filter((o) => !o.used && norm(o.text) === want);
45	    const near = same.sort((a, b) => Math.hypot(a.x - t.x, a.y - t.y) - Math.hypot(b.x - t.x, b.y - t.y))[0];
46	    if (!near) {
47	      // a run split or joined differently: credit by the pieces found near its place
48	      const part = O.filter((o) => !o.used && Math.abs(o.y - t.y) < POS && o.x >= t.x - POS && o.x <= t.x + t.w && want.includes(norm(o.text)));
49	      const got = part.reduce((n, o) => n + norm(o.text).length, 0);
50	      if (got >= want.length * 0.8) { part.forEach((o) => { o.used = true; }); pts += 0.8; tx.matched++; continue; }
51	      tx.missing.push({ x: t.x, y: t.y, text: want });
52	      continue;
53	    }
54	    near.used = true;
55	    const dx = near.x - t.x, dy = near.y - t.y;
56	    const posOk = Math.abs(dx) <= POS && Math.abs(dy) <= POS;
57	    const fontOk = Math.abs((near.pt || 0) - (t.pt || 0)) <= 0.6 && !!near.bold === !!t.bold;
58	    if (posOk && fontOk) { pts += 1; tx.matched++; continue; }
59	    pts += 0.5;
60	    if (!posOk) tx.moved.push({ text: want, dx: +dx.toFixed(2), dy: +dy.toFixed(2) });
61	    if (!fontOk) tx.font.push({ text: want, want: `${t.pt}${t.bold ? 'B' : ''}`, got: `${near.pt}${near.bold ? 'B' : ''}` });
62	  }
63	  tx.extra = O.filter((o) => !o.used).map((o) => ({ x: o.x, y: o.y, text: norm(o.text) }));
64	  const textScore = S.length ? (100 * pts) / (S.length + tx.extra.length * 0.5) : 100;
65	
66	  const RS = rules(src), RO = rules(out).map((r) => ({ ...r, used: false }));
67	  const rl = { source: RS.length, matched: 0, missing: [], extra: [] };
68	  for (const r of RS) {
69	    const o = RO.find((q) => !q.used && q.dir === r.dir && Math.abs(q.pos - r.pos) <= RULE && Math.abs(q.a - r.a) <= RULE + 0.3 && Math.abs(q.b - r.b) <= RULE + 0.3);
70	    if (o) { o.used = true; rl.matched++; } else rl.missing.push(r);
71	  }
72	  rl.extra = RO.filter((q) => !q.used);
73	  const ruleScore = RS.length || rl.extra.length ? (100 * rl.matched) / (RS.length + rl.extra.length * 0.5) : 100;
74	  return { score: +(0.75 * textScore + 0.25 * ruleScore).toFixed(1), textScore: +textScore.toFixed(1), ruleScore: +ruleScore.toFixed(1), texts: tx, rules: rl };
75	}
76	
77	function main(argv) {
78	  if (argv.length < 2) { console.error('usage: node compare-layout.mjs <source.json|.pdf> <printed.json|.pdf> [--out report.json]'); process.exit(2); }
79	  const r = compareLayouts(load(argv[0]), load(argv[1]));
80	  const i = argv.indexOf('--out');
81	  if (i >= 0) writeFileSync(argv[i + 1], JSON.stringify(r, null, 1));
82	  console.log(JSON.stringify({ score: r.score, textScore: r.textScore, ruleScore: r.ruleScore, texts: { source: r.texts.source, matched: r.texts.matched, moved: r.texts.moved.length, font: r.texts.font.length, missing: r.texts.missing.length, extra: r.texts.extra.length }, rules: { source: r.rules.source, matched: r.rules.matched, missing: r.rules.missing.length, extra: r.rules.extra.length } }));
83	}
84	
85	if (import.meta.url === pathToFileURL(process.argv[1] || '').href) main(process.argv.slice(2));

