  const r = { source: (src.images || []).length, matched: 0, missing: [], extra: [] };
  for (const i of src.images || []) {
    const o = IO.find((q) => !q.used && Math.abs(q.x - i.x) <= POS && Math.abs(q.y - i.y) <= POS && Math.abs(q.w - i.w) <= 1 && Math.abs(q.h - i.h) <= 1);
