// Offline geometry check: predicted template border positions (from spec) vs the
// source PDF's visible rules. usage: node geomcheck.mjs <layout.json> <spec.json>
import { readFileSync } from 'node:fs';
const [lf, sf] = process.argv.slice(2);
const page = JSON.parse(readFileSync(lf, 'utf8')).page;
const spec = JSON.parse(readFileSync(sf, 'utf8'));
const light = (c) => typeof c === 'string' && /^#(f[4-9a-f]){3}$/i.test(c);
const srcV = [], srcH = [];
for (const l of page.lines) {
  if (light(l.color) || l.th === 0) continue;
  if (Math.abs(l.x1 - l.x2) < 0.05 && Math.abs(l.y1 - l.y2) > 0.5) srcV.push({ pos: l.x1, a: Math.min(l.y1, l.y2), b: Math.max(l.y1, l.y2) });
  if (Math.abs(l.y1 - l.y2) < 0.05 && Math.abs(l.x1 - l.x2) > 0.5) srcH.push({ pos: l.y1, a: Math.min(l.x1, l.x2), b: Math.max(l.x1, l.x2) });
}
const predV = [], predH = [];
for (const w of spec.windows) for (const n of w.nodes || []) {
  if (n.kind !== 'template') continue;
  let y = w.y + (n.top || 0);
  n.rows.forEach((r, i) => {
    let x = w.x + (n.left || 0);
    r.cols.forEach((cw, j) => {
      const c = (n.cells || []).find((q) => q.row === i + 1 && q.col === j + 1);
      const b = c?.borders || {};
      if (b.l) predV.push({ pos: x, a: y, b: y + r.h });
      if (b.r) predV.push({ pos: x + cw, a: y, b: y + r.h });
      if (b.t) predH.push({ pos: y, a: x, b: x + cw });
      if (b.b) predH.push({ pos: y + r.h, a: x, b: x + cw });
      x += cw;
    });
    y += r.h;
  });
}
// error of each source rule to the nearest predicted rule overlapping it
const err = (src, pred) => src.map((s) => {
  const mid = (s.a + s.b) / 2;
  const cand = pred.filter((p) => p.a - 0.5 <= mid && p.b + 0.5 >= mid);
  return cand.length ? Math.min(...cand.map((p) => Math.abs(p.pos - s.pos))) : null;
}).filter((e) => e !== null && e < 2);
const ev = err(srcV, predV), eh = err(srcH, predH);
const mean = (a) => (a.length ? a.reduce((s, v) => s + v, 0) / a.length : 0);
console.log(JSON.stringify({ v: +mean(ev).toFixed(3), h: +mean(eh).toFixed(3), nv: ev.length, nh: eh.length }));

