  }
}
[...seen].sort((a, b) => b[1].have.length - a[1].have.length).slice(0, 8).forEach(([n, v]) => console.log(n, `(${v.form})`, 'covers', v.have.length + '/' + need.length, v.have.join(','), '| all', v.all.join(',')));
