const item = rep.itemCandidates.find((c) => c.kind === 'items' && c.firstLine[0] === 'R22104496');
const hTop = wins('Artikelnr.')[0].y, zb = wins('Zahlungsbedingungen:')[0];
sh.fields.find((f) => f.text === '54570 Densborn').window = wins('54570 Densborn').find((w) => w.x < 60).name;
const p = wins('114.32');
