  { text: '1', to: '&GS_ITEM-MENGE(C)&' }, { text: 'STÜCK', to: '&GS_ITEM-MEINS&' },
  { text: '114.38', to: '' }, { text: '0.0600', to: '' },
  { text: '114.32', x: p[0].x, to: '&GS_ITEM-NETPR(C)&' }, { text: '114.32', x: p[1].x, to: '&GS_ITEM-NETWR(C)&' },
  { text: '(496551)', to: '&GS_ITEM-IDNLF&' }, { text: 'Y black glossy # 496551', to: '' }] }];
fs.writeFileSync('shape.json', JSON.stringify(sh, null, 1));
console.log('item band', JSON.stringify(item), 'header top', hTop);
EOF
