  '* letterhead / footer text modules per company code (SMARTFORMS > Text module)',
  "CONCATENATE 'Z_HEADER_' is_head-bukrs INTO gv_tm_header.",
  "CONCATENATE 'Z_FOOTER_' is_head-bukrs INTO gv_tm_footer."] };
