S="C:/Users/pssps/AppData/Local/Temp/claude/C--Users-pssps-Documents-Projects-sc4sap-project/505c71fd-30a6-4e9f-b739-7181773da6e9/scratchpad"; cat > "$S/styscan2.mjs" <<'EOF'
import { readdirSync, readFileSync, existsSync } from 'node:fs';
import { styleChoices } from 'file:///C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap/scripts/smartform/plan-form.mjs';
const seen = new Map();
for (const d of readdirSync('.')) {
  const f = `${d}/${d}.content.json`; if (!existsSync(f)) continue;
  let c; try { c = JSON.parse(readFileSync(f, 'utf8')); } catch { continue; }
  for (const s of c.styles || []) {
    if (seen.has(s.name)) continue;
    const ch = styleChoices([s]);
    const h = [...new Set(ch.filter((x) => /^HELVE/.test(x.fam)).map((x) => x.pt + (x.bold ? 'B' : '')))];
    const c2 = [...new Set(ch.filter((x) => /^COUR/.test(x.fam)).map((x) => x.pt + (x.bold ? 'B' : '')))];
    if (c2.length && h.length) seen.set(s.name, { form: d, h: h.sort().join(','), c: c2.sort().join(',') });
  }
}
for (const [n, v] of seen) console.log(n, `(${v.form})`, '| HELVE', v.h, '| COURIER', v.c);
EOF
cd /c/Users/pssps/Documents/Projects/sc4sap_project/.sc4sap/work/HKT-DEV/mcp-output/smartforms; node "$S/styscan2.mjs"

