const GW = require('C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap/scripts/smartform/glyph-widths.json').widths;
const S = 210 / 1008, X = (px) => +((px - 3) * S).toFixed(2), Y = (px) => +((px - 2) * S).toFixed(2);
