const w1 = (t, b, fam) => { let s = 0; for (const ch of t) { const c = ch.charCodeAt(0); s += (c >= 32 && c - 32 < tab(fam, b).length ? tab(fam, b)[c - 32] : 556) || 556; } return s / 1000 * 0.3528; };
