  // short texts: the size of their line's neighbours
  const pt = raw ? SIZES.reduce((p, s) => (Math.abs(s - raw) < Math.abs(p - raw) ? s : p), 9) : null;
  runs.push({ a, yc, text, bold: !!bold, fam, pt });
}
