  x: X(r.a), y: +(Y(r.yc) + 0.27 * r.pt * 0.3528).toFixed(2), w: +(w1(r.text, r.bold, r.fam) * r.pt).toFixed(2), text: r.text, pt: r.pt, bold: r.bold,
  font: r.fam === 'COURIER' ? 'Courier' : r.bold ? 'Helvetica-Bold' : 'Helvetica', sapFont: { device: 'PDFUC', family: r.fam, bold: r.bold },
}));
