const images = [{ x: X(3), y: Y(40), w: +((1011 - 3) * S).toFixed(2), h: +((130 - 40) * S).toFixed(2) }];
require('fs').writeFileSync('layout.json', JSON.stringify({ file: 'TEST2.png', source: 'screenshot (positions estimated)', pages: 1, page: { no: 1, widthMm: 210, heightMm: 297, runs: out, lines, rects: [], images } }, null, 1));
const c = {}; out.forEach((r) => { const k = r.sapFont.family + ' ' + r.pt + (r.bold ? 'B' : ''); c[k] = (c[k] || 0) + 1; }); console.log(out.length, 'runs', JSON.stringify(c));
